 const credits=createCreditUI({...ctx,button,area,check,openTax:id=>taxOpen(id)});
 let financeTab='Invoices',timeTab='My HR',commsTab='Letters & QR',taxPage=0;
 const tabs=(name,values,current)=>`<div class="actions subnav">${values.map(v=>button(name,v,v,`class="${v===current?'primary':''}"`)).join('')}</div>`;
 const creditFor=i=>(s().advances||[]).filter(a=>a.client_id===i.client_id&&a.firm_id===i.firm_id&&Number(a.balance)>0&&(!a.project_id||a.project_id===i.project_id)),creditTotal=i=>round(creditFor(i).reduce((t,a)=>t+Number(a.balance),0));
 function finance(){
  const firm=ctx.firm(),invoices=s().invoices.filter(i=>!firm||i.firm_id===firm),payments=s().payments.filter(i=>!firm||i.firm_id===firm),feeSchedules=(s().recurring_fees||[]).filter(x=>ctx.filtered().projects.some(p=>p.project_id===x.project_id&&(!firm||p.handling_firm_id===firm)));
  let body='';
  if(financeTab==='Invoices')body=`<div class="section-head"><p class="muted">KES · Draft → Posted → payments. Posted numbers and amounts are retained. These are testing records. The ERP does not submit to eTIMS: issue the invoice on the eTIMS portal, then record its eTIMS number here.</p>${partner()?button('invoice-new','+ New invoice'):''}</div>`+table(['Invoice / client','Handling firm','Due date','Total','Paid / balance','Status','Action'],invoices.map(i=>[`${esc(i.invoice_number||'Draft')}<small>${esc(clientName(i.client_id))}</small>${i.status==='Posted'?(i.etims?`<small>eTIMS ${esc(i.etims.etims_invoice_no)} · ${shortDate(i.etims.etims_issued_on)}</small>`:'<small class="error">eTIMS reference missing · the PDF is marked not a valid eTIMS invoice</small>'):''}`,esc(firmName(i.firm_id)),shortDate(i.due_date),money(i.total_amount),`${money(i.paid_amount)}<small>Balance ${money(Number(i.total_amount)-Number(i.paid_amount))}</small>`,badge(i.status),button('invoice-view','View / print',i.invoice_id)+(partner()&&i.status==='Draft'?button('invoice-post','Post',i.invoice_id):'')+(partner()&&i.status==='Posted'&&Number(i.paid_amount)<Number(i.total_amount)?button('payment-new','Record payment',i.invoice_id):'')+(partner()&&i.status==='Posted'&&Number(i.paid_amount)<Number(i.total_amount)&&creditTotal(i)>0?button('advance-apply',`Apply advance (${money(creditTotal(i))})`,i.invoice_id):'')+(partner()&&i.status==='Posted'&&!i.etims?button('etims-record','Record eTIMS number',i.invoice_id):'')+(partner()&&i.status!=='Void'?button('invoice-void','Void',i.invoice_id):'')]),'Status');
  if(financeTab==='Recurring fees')body=`<p class="muted">Set the agreed fee before VAT, frequency and dates once for each project. ERP-generated invoices remain drafts for review; posting and sending are separate. Pause or cancel affects future drafts only, not invoices already created.</p><div class="actions">${partner()?button('fee-new','+ Set up recurring fee'):''}</div>`+table(['Project / invoice description','Fee before VAT','VAT rate','Frequency / dates','Status','Actions'],feeSchedules.map(f=>{const p=d().projects.find(x=>x.project_id===f.project_id),generated=s().invoices.filter(i=>i.recurring_fee_schedule_id===f.fee_schedule_id&&!i.deleted_at).length;return [`${esc(projectName(f.project_id))}<small>${esc(f.description)}</small>`,money(f.amount_ex_vat),`${Number(f.vat_rate||0)}%`,`${esc(f.frequency)}<small>${shortDate(f.starts_on)} – ${f.ends_on?shortDate(f.ends_on):'No end date'}</small>`,badge(f.status)+`<small>${generated} invoice draft(s) created</small>`,(leader()&&f.status==='Active'?button('fee-generate','Create due drafts',f.fee_schedule_id):'')+(leader()&&f.status==='Active'?button('fee-pause','Pause',f.fee_schedule_id):'')+(leader()&&f.status==='Paused'?button('fee-resume','Resume',f.fee_schedule_id):'')+(leader()&&['Active','Paused'].includes(f.status)?button('fee-cancel','Cancel future fees',f.fee_schedule_id):'')];}));
  const advances=(s().advances||[]).filter(a=>!firm||a.firm_id===firm);
  if(financeTab==='Payments')body=`<div class="section-head"><div><h3>Advances received</h3><p class="muted">Money received before an invoice exists. It is a liability to the client, not income, until applied. It is held by the firm that received it and can be applied only to that firm's invoices (optionally limited to one project). An advance receipt is not a tax invoice; the VAT treatment of advances is for the Partner to review.</p></div>${partner()?button('advance-new','+ Record advance'):''}</div>`+table(['Receipt','Client','Firm / project','Received','Reference','Amount','Applied','Refunded / moved','Credit left','Action'],advances.map(a=>{const applied=(s().payments||[]).filter(x=>x.advance_id===a.advance_id).reduce((t,x)=>t+Number(x.amount),0),moved=(s().advance_movements||[]).filter(x=>x.advance_id===a.advance_id).reduce((t,x)=>t+Number(x.amount),0);return [esc(a.receipt_number),esc(clientName(a.client_id)),`${esc(firmName(a.firm_id))}<small>${a.project_id?esc(projectName(a.project_id)):'Client level · any project'}</small>`,`${shortDate(a.received_date)}<small>${esc(a.method)}</small>`,esc(a.reference),money(a.amount),money(applied),money(moved),money(a.balance),leader()&&Number(a.balance)>0?button('advance-refund','Refund',a.advance_id)+button('advance-transfer','Move to another firm',a.advance_id):''];}))+`<h3 class="section-space">Advance refunds and transfers</h3><p class="muted">Refunds and transfers are recorded once and cannot be edited. A transfer creates a matching advance in the receiving firm. A Partner or Manager with finance access records them.</p>`+table(['Voucher','Date','Type','From advance','Amount','Reference','Reason'],(s().advance_movements||[]).filter(m=>!firm||m.firm_id===firm).map(m=>{const from=advances.find(x=>x.advance_id===m.advance_id),to=m.to_advance_id?advances.find(x=>x.advance_id===m.to_advance_id):null;return [esc(m.voucher_number),shortDate(m.movement_date),esc(m.kind)+(m.method?`<small>${esc(m.method)}</small>`:''),`${esc(from?.receipt_number||'')}<small>${esc(firmName(m.firm_id))}</small>`,money(m.amount),esc(m.reference),esc(m.reason)+(to?`<small>To ${esc(to.receipt_number)} · ${esc(firmName(to.firm_id))}</small>`:'')];}))+`<h3 class="section-space">Payments applied to invoices</h3>`+table(['Receipt','Invoice','Firm','Date / method','Reference','Amount','Action'],payments.map(p=>[esc(p.receipt_number),esc(s().invoices.find(i=>i.invoice_id===p.invoice_id)?.invoice_number),esc(firmName(p.firm_id)),`${shortDate(p.payment_date)}<small>${esc(p.method)}</small>`,esc(p.reference),money(p.amount),partner()&&!p.reverses_id&&!s().payments.some(x=>x.reverses_id===p.payment_id)?button('payment-reverse','Reverse',p.payment_id):'']));
  if(financeTab==='Statements')body=`<p>Generate one client statement across authorised firms. Each invoice and payment retains its issuing firm; balances are calculated from posted invoices and allocated payments.</p>${button('statement','Generate statement')}`;
  if(financeTab==='Budgets & WIP')body=`<p>Approved time is costed using the staff rate applicable on the work date. Missing rates are shown as incomplete. Remaining agreed fees are shown separately from costs.</p><div class="actions">${partner()?button('budget','+ Add fee / budget version'):''}${button('wip','Open profitability report')}</div>`+table(['Project','Effective date','Agreed fee','Budget hours','Budget cost','Billing'],s().budgets.filter(b=>ctx.filtered().projects.some(p=>p.project_id===b.project_id)).map(b=>[esc(projectName(b.project_id)),shortDate(b.effective_from),money(b.agreed_fee),esc(b.budgeted_hours),money(b.budgeted_cost),button('task-billing','Billed by task',b.project_id)]));
  return `<section class="card"><h2>Finance & Reports</h2>${tabs('finance-tab',['Invoices','Recurring fees','Payments','Statements','Budgets & WIP'],financeTab)}${body}</section>`;
 }
 function communications(){
  const intern=d().me.category_code==='INTERN';if(intern&&commsTab!=='Internal chat')commsTab='Support';
  if(d().me.category_code==='ADMIN')return `<section class="card"><div class="section-head"><div><h2>Chat</h2><p class="muted">Create chat groups and choose who is in them. You cannot read a group’s messages unless you are a member.</p></div><button type="button" class="primary" data-messenger-open>Open chat</button></div></section>`;
  if(commsTab==='Client services'&&!intern)return `<section class="card"><div class="section-head"><h2>Client services</h2></div>${tabs('comms-tab',['Letters & QR','Communications','Client services','Internal chat','Support'],commsTab)}${clientSupport.view()}</section>`;
  if(commsTab==='Internal chat')return `<section class="card">${tabs('comms-tab',intern?['Internal chat','Support']:['Letters & QR','Communications','Client services','Internal chat','Support'],commsTab)}<p>One-to-one chats, groups and project discussions now live in the <b>Chat</b> button at the top of every page.</p><button type="button" class="primary" data-messenger-open>Open chat</button></section>`;
  const letters=commsTab==='Letters & QR',list=s().communications.filter(c=>(!ctx.firm()||c.firm_id===ctx.firm())&&(!letters||c.channel==='Letter'));
  return `<section class="card"><div class="section-head"><h2>Communication hub</h2>${!intern?button('letter-new','+ Create letter','','class="primary"'):''}</div>${tabs('comms-tab',intern?['Internal chat','Support']:['Letters & QR','Communications','Client services','Internal chat','Support'],commsTab)}${commsTab==='Support'?support():`<p class="muted">${letters?'Create and print client letters here. The ERP keeps a separate staff-only QR in the letter preview; it requires staff sign-in and is not printed on the client copy.':'Record calls, emails, meetings and visits. Logging a communication does not send an email. Open a record to review its details.'}</p>${!letters?button('communication-new','+ Log communication')+' '+(['PARTNER','MANAGER','SUPERVISOR'].includes(d().me.category_code)?button('incoming-timeline-pick','Client timeline'):''):''}${table(['Date / reference','Client / firm','Subject / purpose','Follow-up','Status','Action'],list.map(c=>[`${shortDate(c.communication_date)}<small>${esc(c.reference)}${c.channel!=='Letter'?' · '+esc(c.channel)+(c.direction?' ('+esc(c.direction.toLowerCase())+')':''):''}</small>`,`${esc(clientName(c.client_id))}<small>${esc(firmName(c.firm_id))}</small>`,`${esc(c.subject)}<small>${esc(c.purpose)}</small>`,shortDate(c.followup_date),badge(c.status),button(c.channel==='Letter'?'communication-qr':'communication-view',c.channel==='Letter'?'Open letter & staff QR':'Open record',c.communication_id)+button('communication-edit',c.channel==='Letter'?'Edit letter':'Edit',c.communication_id)]),'Status')}${!list.length?empty(letters?'No letters yet. Select Create letter to prepare one.':'No communications yet. Log a client call, email or meeting.'):''}`}</section>`;
 }
 function support(){return `<div class="section-head"><p>Raise an internal support request and track its first-response deadline. Notifications remain inside the ERP.</p>${button('ticket-new','+ New ticket')}</div>${table(['Ticket','Subject','Assigned to','Priority / response due','Status','Action'],s().tickets.map(t=>[esc('ALC-'+t.ticket_number),esc(t.subject),esc(staffName(t.assigned_to)),`${badge(t.priority)}<small>${new Date(t.sla_due_at).toLocaleString('en-GB',{timeZone:'Africa/Nairobi'})}</small>${!t.first_response_at&&new Date(t.sla_due_at)<new Date()?'<span class="missing">Response overdue</span>':''}`,badge(t.status),button('ticket','Open',t.ticket_id)]))}`;}
 function adminSettings(){return `<section class="card"><div class="section-head"><h2>System settings</h2></div><p class="muted">A System Administrator keeps the application lists and reference material up to date. You do not see or change client records, and you cannot approve anything. Tax rules, chart of accounts changes and release decisions stay with Managers and Partners.</p><div class="actions"><button type="button" data-v6="sector">+ Add sector</button>${button('references','Private reference documents')}${button('release-read','Go-live readiness (read only)')}</div></section><section class="card section-space"><h3>Sectors</h3>${(d().sectors||[]).map(x=>`<span class="badge">${esc(x.name)}</span>`).join(' ')||empty('No sectors yet.')}</section>`;}
 function settings(){if(d().me.category_code==='ADMIN')return adminSettings();return `${settingsHub.card()}<section class="card"><div class="section-head"><h2>Reference documents & change control</h2>${button('references','Open private reference documents')}</div><p>Review the consolidated Word specifications and retain each approved version inside the ERP.</p></section><section class="card"><h2>Chart of accounts</h2><p>Attached account master, controlled additions and separate tax rules.</p><button type="button" data-accounting="catalog">Browse chart of accounts</button></section>${deadlines.card()}${taxRoles.card()}${dueBacklog.card()}${taxConfig.rates()}${starterConfirm.card()}
  ${partner()?`<section class="card section-space"><div class="section-head"><h2>Staff cost & billing rates</h2>${button('staff-rate','+ Add rate period')}</div>${table(['Staff','Effective dates','Cost / hour','Billable / hour'],s().staff_rates.map(r=>[esc(staffName(r.staff_id)),`${shortDate(r.effective_from)} – ${shortDate(r.effective_to)}`,money(r.cost_rate),money(r.billable_rate)]))}</section><section class="card section-space"><div class="section-head"><h2>Handling firms</h2><button data-new="firm">+ Add firm</button></div>${table(['Firm','Registered name','Invoice prefix','Action'],d().firms.map(f=>[esc(f.firm_code),esc(f.legal_name),esc(f.invoice_prefix||'INV/'+f.firm_code),button('firm','Edit details',f.firm_id)]))}</section>`:''}`;}
 function hr(){
  const me=d().me.staff_id,open=s().attendance.find(x=>x.staff_id===me&&date(x.work_date)===today()),mine=s().leave.filter(l=>l.staff_id===me),team=leader();
  return `<section class="card section-space"><h2>HR & attendance</h2>${tabs('hr-tab',team?['My HR','Leave approvals','Team planner','Credentials']:['My HR','Credentials'],timeTab)}${timeTab==='My HR'?`<div class="actions">${!open?button('clock-in','Clock in'):open.clock_in&&!open.clock_out?button('clock-out','Clock out'):badge(open.status+' · '+(open.clock_out?'Clocked out':'Today'))}${button('leave-new','+ Request leave')}${button('credential-new','+ Add credential / CPD')}</div><h3 class="section-space">My leave</h3>${table(['Dates','Type','Working days','Status','Review'],mine.map(l=>[`${shortDate(l.starts_on)} – ${shortDate(l.ends_on)}`,esc(l.leave_type),l.working_days,badge(l.status),esc(l.review_note||'')]))}<h3 class="section-space">My attendance</h3>${attendanceRows(s().attendance.filter(t=>t.staff_id===me))}`:timeTab==='Leave approvals'?table(['Staff','Dates','Type / busy season','Status','Action'],s().leave.map(l=>[esc(staffName(l.staff_id)),`${shortDate(l.starts_on)} – ${shortDate(l.ends_on)}`,esc(l.leave_type)+(l.busy_season?'<small>Partner approval required</small>':''),badge(l.status),l.status==='Pending'&&l.staff_id!==me?button('leave-review','Review',l.leave_id):''])):timeTab==='Team planner'?`<div class="actions">${button('roster','Schedule assignment')}${button('performance','Record engagement feedback')}</div>${table(['Staff','Project / firm','Dates','Allocation'],d().assignments.filter(a=>a.start_date).map(a=>[esc(staffName(a.staff_id)),`${esc(projectName(a.project_id))}<small>${esc(firmName(d().projects.find(p=>p.project_id===a.project_id)?.handling_firm_id))}</small>`,`${shortDate(a.start_date)} – ${shortDate(a.end_date)}`,esc(a.allocation_percentage)+'%']))}<h3 class="section-space">Team attendance</h3>${attendanceRows(s().attendance)}`:`${button('credential-new','+ Add credential / CPD')}${table(['Staff','Credential','Status','Hours / expiry','Verification'],s().credentials.map(c=>[esc(staffName(c.staff_id)),`${esc(c.credential_type)}<small>${esc(c.description)}</small>`,badge(c.status),`${esc(c.cpd_hours)} CPD hours<small>${shortDate(c.expiry_date)}</small>`,c.verified_by?esc(staffName(c.verified_by)):team&&c.staff_id!==me?button('credential-verify','Verify',c.credential_id):'Awaiting verification']))}`}</section>`;
 }
 const attendanceRows=rows=>table(['Staff / date','Location','Clock in / out','Status','Action'],rows.slice(0,60).map(t=>[`${esc(staffName(t.staff_id))}<small>${shortDate(t.work_date)}</small>`,esc(t.location),`${t.clock_in?new Date(t.clock_in).toLocaleTimeString('en-GB',{timeZone:'Africa/Nairobi'}):'—'} / ${t.clock_out?new Date(t.clock_out).toLocaleTimeString('en-GB',{timeZone:'Africa/Nairobi'}):'—'}`,badge(t.status)+(t.review_required?'<small class="missing">Estimated attendance — review required</small>':''),leader()&&t.staff_id!==d().me.staff_id&&t.clock_in?button('attendance-correct','Correct with reason',t.attendance_id):'']),'Status');
 function taxList(){const cases=s().tax_cases.filter(c=>ctx.filtered().projects.some(p=>p.project_id===c.project_id));modal('Tax preparation & filing packs',`${d().me.category_code!=='INTERN'?button('tax-new','+ New tax period'):''}<p class="muted section-space">Prepare and review each obligation for the client’s reporting period. The download is a staff filing pack with reconciliations and return-entry schedules. Staff still complete the current official KRA return and retain its acknowledgment and payment reference in the linked task. The ERP does not submit returns to KRA.</p>${cases.length?table(['Project','Obligation / period','ERP status','Action'],cases.map(c=>[esc(projectName(c.project_id)),`${esc(c.kind)}${c.amendment_no?` · <b>Amendment ${c.amendment_no}</b>`:''}<small>${shortDate(c.starts_on)} – ${shortDate(c.ends_on)}</small>`,badge(c.status),button('tax-open','Open filing pack',c.case_id)+(c.status==='Filed'&&d().me.category_code!=='INTERN'&&['PARTNER','MANAGER','SUPERVISOR'].includes(d().me.category_code)&&!s().tax_cases.some(x=>x.project_id===c.project_id&&x.kind===c.kind&&x.starts_on===c.starts_on&&x.ends_on===c.ends_on&&(x.amendment_no||0)>(c.amendment_no||0))?button('tax-amend','Amend this filed return',c.case_id):'')])):'<div class="info section-space"><b>No tax periods yet</b><p>Create a period after confirming the client reporting dates and required source data. Until the inputs and reviews are complete, the tax position will be shown as Not ready.</p></div>'}`);}
