 const employeeInputs=(e={})=>`<fieldset data-employee class="full"><legend>Employee</legend><div class="form-grid">${[['name','Employee name','text'],['gross','Cash gross salary KES','number'],['taxable_benefits','Taxable benefits KES','number'],['other_pension','Other registered pension contribution','number'],['mortgage_interest','Qualifying mortgage interest','number'],['postretirement_medical','Registered post-retirement medical contribution','number'],['insurance_premium','Qualifying insurance premium','number'],['approved_exemption','Approved exemption amount','number'],['source_paye','P10 PAYE','number'],['evidence_reference','Relief / exemption evidence','text']].map(([k,l,t])=>`<label>${l}<input data-value="${k}" type="${t}" value="${esc(e[k]??(t==='number'?0:''))}" ${t==='number'?'min="0" step="0.01" required':k==='name'?'required':''}></label>`).join('')}<label><input data-value="resident" type="checkbox" ${e.resident!==false?'checked':''}>Resident personal relief applies</label><details class="full"><summary>Different statutory contribution bases</summary><p>Leave blank to use cash gross salary. Explain any different base.</p>${[['pensionable_pay','NSSF pensionable pay'],['shif_base','SHIF gross base'],['housing_levy_base','Housing levy gross base']].map(([k,l])=>`<label>${l}<input data-value="${k}" type="number" min="0" step="0.01" value="${e[k]??''}"></label>`).join('')}<label>Basis explanation<input data-value="base_reason" value="${esc(e.base_reason||'')}"></label></details></div></fieldset>`;
