  if(action==='staff-rate'){actionForm('Staff cost and billing rate',select('staff_id','Staff *',d().staff.map(x=>[x.staff_id,x.full_name]))+field('effective_from','From *',today(),'date','required')+field('effective_to','Through *',today().slice(0,4)+'-12-31','date','required')+field('cost_rate','Internal cost / hour KES *','','number','required min="0" step="0.01"')+field('billable_rate','Billable rate / hour KES *','','number','required min="0" step="0.01"'),'staff_rate_add');return;}
  if(action==='firm'){const f=d().firms.find(x=>x.firm_id===id);modal('Firm details',form(field('legal_name','Legal name *',f.legal_name,'text','required')+field('kra_pin','KRA PIN',f.kra_pin||'')+field('email','Email',f.email||'','email')+field('phone','Phone',f.phone||'')+field('physical_address','Address',f.physical_address||'')+field('invoice_prefix','Invoice prefix',f.invoice_prefix||'INV/'+f.firm_code)+select('invoice_numbering','Invoice numbering',[['yearly','Restart each year (INV/ACL/2026/00001)'],['continuous','Continuous, no year (INV/ACL/00323)']],f.invoice_numbering||'yearly')+field('invoice_last_number','Last invoice number already used (continuous only, to carry on from the old system)','','number','min="0" step="1"')+select('vat_registered','VAT registration confirmed',['Yes','No'],f.vat_registered==null?'':f.vat_registered?'Yes':'No')+area('payment_instructions','Authorised bank / M-Pesa / other payment instructions',f.payment_instructions||'')),data=>request({action:'firm_details',...val(data),firm_id:id,vat_registered:data.get('vat_registered')==='Yes'}));$('#editForm').elements.vat_registered.required=true;$('#editForm').insertAdjacentHTML('beforeend',`<p class="full">Invoice logo: ${f.has_logo?'uploaded':'none yet'} ${button('firm-logo','Upload or replace logo',id)}</p>`);return;}
  if(action==='invoice-new'){invoiceNew();return;}if(action==='invoice-view'){invoice(id);return;}
